set -e
C=$OCI_TENANCY
echo "① 네트워크 만드는 중..."
VCN=$(oci network vcn list -c $C --display-name msr-vcn --query 'data[0].id' --raw-output 2>/dev/null || true)
if [ -z "$VCN" ] || [ "$VCN" = "None" ]; then
VCN=$(oci network vcn create -c $C --cidr-block 10.0.0.0/16 --display-name msr-vcn --dns-label msrvcn --wait-for-state AVAILABLE --query 'data.id' --raw-output)
IGW=$(oci network internet-gateway create -c $C --vcn-id $VCN --is-enabled true --display-name msr-igw --wait-for-state AVAILABLE --query 'data.id' --raw-output)
RT=$(oci network vcn get --vcn-id $VCN --query 'data."default-route-table-id"' --raw-output)
oci network route-table update --rt-id $RT --force --route-rules "[{\"destination\":\"0.0.0.0/0\",\"destinationType\":\"CIDR_BLOCK\",\"networkEntityId\":\"$IGW\"}]" >/dev/null
SL=$(oci network vcn get --vcn-id $VCN --query 'data."default-security-list-id"' --raw-output)
oci network security-list update --security-list-id $SL --force --ingress-security-rules '[{"source":"0.0.0.0/0","protocol":"6","tcpOptions":{"destinationPortRange":{"min":22,"max":22}}},{"source":"0.0.0.0/0","protocol":"6","tcpOptions":{"destinationPortRange":{"min":80,"max":80}}},{"source":"0.0.0.0/0","protocol":"6","tcpOptions":{"destinationPortRange":{"min":443,"max":443}}}]' >/dev/null
oci network subnet create -c $C --vcn-id $VCN --cidr-block 10.0.0.0/24 --display-name msr-sub --dns-label msrsub --wait-for-state AVAILABLE >/dev/null
fi
SUB=$(oci network subnet list -c $C --vcn-id $VCN --query 'data[0].id' --raw-output)
echo "💰 예산 알림 확인 (1달러만 넘어도 메일)..."
if [ -z "$(oci budgets budget list -c $C --query 'data[?"display-name"==`msr-1usd`].id | [0]' --raw-output 2>/dev/null | grep -v None)" ]; then
  EM=$(oci iam user list -c $C --query 'data[0].email' --raw-output 2>/dev/null); [ -n "$EM" ] && [ "$EM" != "None" ] || EM=chkchp0702@gmail.com
  BID=$(oci budgets budget create -c $C --display-name msr-1usd --amount 1 --reset-period MONTHLY --target-type COMPARTMENT --targets "[\"$C\"]" --query 'data.id' --raw-output 2>/dev/null || true)
  if [ -n "$BID" ] && [ "$BID" != "None" ]; then
    oci budgets alert-rule create --budget-id $BID --type ACTUAL --threshold 1 --threshold-type PERCENTAGE --recipients "$EM" --display-name msr-1usd-alert --message "Oracle 요금이 생기기 시작함 — Claude에게 알려 주세요" >/dev/null 2>&1 && echo "   ✅ 예산 알림 걸어 둠 → $EM" || echo "   ⚠ 알림 규칙은 못 만듦(서버 만들기는 계속)"
  else echo "   ⚠ 예산은 못 만듦(서버 만들기는 계속)"; fi
else echo "   이미 걸려 있음"; fi
echo "② 우분투 24.04 이미지 찾는 중..."
IMG=$(oci compute image list -c $C --operating-system "Canonical Ubuntu" --operating-system-version "24.04" --shape VM.Standard.A1.Flex --sort-by TIMECREATED --query 'data[0].id' --raw-output)
[ -f ~/.ssh/id_rsa ] || ssh-keygen -t rsa -b 4096 -N "" -f ~/.ssh/id_rsa -q
ID=$(oci compute instance list -c $C --display-name msr --lifecycle-state RUNNING --query 'data[0].id' --raw-output 2>/dev/null || true)
if [ -z "$ID" ] || [ "$ID" = "None" ]; then
echo "③ 서버 만드는 중 — 자리가 날 때까지 1분마다 다시 시도 (최대 ${TRIES:-15}번 · 이 화면 그대로 두세요)..."
ID=""
ADS=$(oci iam availability-domain list -c $C --query 'data[].name' --raw-output | tr -d '[]",')
for T in $(seq 1 ${TRIES:-15}); do
  for SH in '{"ocpus":2,"memoryInGBs":12}' '{"ocpus":1,"memoryInGBs":6}'; do
    for AD in $ADS; do
      ID=$(oci compute instance launch -c $C --availability-domain "$AD" --shape VM.Standard.A1.Flex --shape-config "$SH" --display-name msr --image-id $IMG --subnet-id $SUB --assign-public-ip true --ssh-authorized-keys-file ~/.ssh/id_rsa.pub --boot-volume-size-in-gbs 50 --wait-for-state RUNNING --query 'data.id' --raw-output 2>/tmp/err.txt) && break 3
      ID=""; sleep 8; echo "  [$T번째] $(echo $SH | tr -d '{}\"') 자리 없음: $(grep -o '"message": "[^"]*"' /tmp/err.txt | head -1 | cut -c13-)"
    done
  done
  [ $T -lt ${TRIES:-15} ] && sleep 90
done
fi
[ -n "$ID" ] || { echo "❌ 서버를 못 만듦 — 위 실패 메시지를 캡처해 주세요"; exit 1; }
IP=$(oci compute instance list-vnics --instance-id $ID --query 'data[0]."public-ip"' --raw-output)
echo "$IP" > ~/msr_ip.txt
echo "✅ 서버 만들어짐: $IP"
echo "④ 서버 안에 휴대폰용 설치 화면 여는 중 (5~10분 · 다른 앱으로 넘어가지 마세요)..."
SSHO="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=8 -o BatchMode=yes -o LogLevel=ERROR"
for i in $(seq 1 40); do ssh -n $SSHO ubuntu@$IP true </dev/null 2>/dev/null && break; sleep 10; done
ssh $SSHO ubuntu@$IP "sudo bash -s $IP" <<'BOOT' | tee ~/msr_phone.txt
set -e
IP="$1"; HOST="$(echo "$IP" | tr . -).sslip.io"
cloud-init status --wait </dev/null >/dev/null 2>&1 || true
export DEBIAN_FRONTEND=noninteractive
for i in 1 2 3 4 5 6; do apt-get update -q </dev/null >/dev/null 2>&1 && apt-get install -y -q python3 unzip iptables-persistent </dev/null >/dev/null 2>&1 && break; echo "   (설치 대기 $i)"; sleep 20; done
apt-get install -y -q caddy </dev/null >/dev/null 2>&1 || {
  apt-get install -y -q debian-keyring debian-archive-keyring apt-transport-https curl gnupg </dev/null >/dev/null 2>&1
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --dearmor --yes -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  apt-get update -q </dev/null >/dev/null 2>&1; apt-get install -y -q caddy </dev/null >/dev/null 2>&1; }
command -v caddy >/dev/null || { echo "❌ caddy 설치 실패 — 이 화면을 캡처해 주세요"; exit 1; }
mkdir -p /srv/upload/files /srv/msr/www
[ -s /srv/upload/.token ] || (head -c 18 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 20 > /srv/upload/.token)
chmod 600 /srv/upload/.token
echo "" | base64 -d > /srv/upload/up.py
cat > /etc/systemd/system/msr-up.service <<UNIT
[Unit]
Description=CH Investing phone installer
After=network.target
[Service]
ExecStart=/usr/bin/python3 /srv/upload/up.py
Restart=always
[Install]
WantedBy=multi-user.target
UNIT
cat > /etc/caddy/Caddyfile <<CADDY
$HOST {
	handle /up* {
		reverse_proxy 127.0.0.1:8099
	}
	handle {
		root * /srv/msr/www
		header Access-Control-Allow-Origin *
		header Cache-Control "public, max-age=60"
		@hidden path /.git* /.github/*
		respond @hidden 404
		file_server
	}
}
CADDY
iptables -C INPUT -p tcp -m multiport --dports 80,443 -j ACCEPT 2>/dev/null || iptables -I INPUT 1 -p tcp -m multiport --dports 80,443 -j ACCEPT
netfilter-persistent save </dev/null >/dev/null 2>&1 || true
systemctl daemon-reload </dev/null; systemctl enable --now msr-up </dev/null >/dev/null 2>&1; systemctl restart msr-up </dev/null
systemctl enable caddy </dev/null >/dev/null 2>&1; systemctl restart caddy </dev/null
# 📮 11/27 받은편지함 v3 + 아침 리포트 작업 — Claude 예약 작업(두뇌·아침 리포트·백테스트 등)의 결과 파일을 daily-app/inbox/msr 에서 가져와 반영
#   (자료 파일만 받음 · 켤 수 있는 건 이 서버에 이미 있는 작업뿐 · 1분마다 새 것 확인)
if [ -d /srv/msr/kit/jobs ]; then
  echo "" | base64 -d | tar xz -C /srv/msr
  chmod +x /srv/msr/extras/tick.sh /srv/msr/extras/jobs/*/run.sh; chown -R msr:msr /srv/msr/extras
  for j in inbox morning-pre morning-build review; do mkdir -p /srv/msr/kit/jobs/$j; cp /srv/msr/extras/jobs/$j/run.sh /srv/msr/extras/jobs/$j/group /srv/msr/kit/jobs/$j/; chown -R msr:msr /srv/msr/kit/jobs/$j; done
  mkdir -p /srv/msr/locks; chown msr:msr /srv/msr/locks
  rm -f /etc/cron.d/msr-inbox
  printf 'SHELL=/bin/bash\nPATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin\nMSR_ROOT=/srv/msr\n* * * * * msr flock -n /srv/msr/locks/tick.lock /srv/msr/extras/tick.sh >/dev/null 2>&1\n24 21 * * * msr /srv/msr/kit/run_job.sh morning-pre >/dev/null 2>&1\n' > /etc/cron.d/msr-extras
  chmod 644 /etc/cron.d/msr-extras
  sudo -u msr flock -n /srv/msr/locks/tick.lock /srv/msr/extras/tick.sh </dev/null >/dev/null 2>&1 || true
  echo "   (아침 준비 계산을 시험으로 한 번 돌리는 중 · 1~3분)"
  sudo -u msr MSR_ROOT=/srv/msr /srv/msr/kit/run_job.sh morning-pre </dev/null >/dev/null 2>&1 || true
  echo "   시험: $(tail -n 1 /srv/msr/logs/_history.log 2>/dev/null)"
  echo "   작업: $(ls /srv/msr/kit/jobs | grep -E '^(inbox|morning-pre|morning-build|review)$' | tr '\n' ' ')"
  echo "📮 받은편지함 v3 + 아침 리포트 작업 켬 (1분마다 확인)"
fi
sleep 20
echo ""
echo "=============================================="
echo "✅ 완료! 이 화면을 캡처해서 Claude에게 보내 주세요"
echo "📱 휴대폰에서 열 주소:"
echo "https://$HOST/up/?k=$(cat /srv/upload/.token)"
echo "=============================================="
BOOT
